// ---- email.js (source: apps/workflows/src/code/email.js — edit there, then rebuild) ----
const email = (() => { const module = { exports: {} };
// Workflow C helpers: personalised, honest, mobile-first email + the unsubscribe token.
//
// Content rules (docs/DESIGN.md §9.9): lender named on every card, rate exactly as published,
// "why you qualify" from the user's own data, unverifiable conditions shown openly, no PII in
// links, HTML escaped (names come from a spreadsheet), plain-text twin, well under Gmail's
// ~102 KB clipping limit.

const crypto = require("crypto");

const b64url = (buf) => Buffer.from(buf).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

/** Identical to packages/notifications (Go); a contract test checks both. */
function unsubscribeToken(userId, secret, nowSeconds, ttlSeconds = 90 * 24 * 3600) {
  const payload = `${b64url(Buffer.from(String(userId), "utf8"))}.${nowSeconds + ttlSeconds}`;
  const sig = crypto.createHmac("sha256", secret).update(payload).digest().subarray(0, 16);
  return `${payload}.${b64url(sig)}`;
}

const escapeHtml = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

/** Indian digit grouping without relying on ICU: 150000 → "1,50,000". */
function formatINR(value) {
  const n = Math.round(Number(value));
  if (!Number.isFinite(n)) return "";
  const s = String(Math.abs(n));
  const last3 = s.slice(-3);
  const rest = s.slice(0, -3).replace(/\B(?=(\d{2})+(?!\d))/g, ",");
  return (n < 0 ? "-" : "") + "₹" + (rest ? `${rest},${last3}` : last3);
}

function rateText(p) {
  const lo = p.interest_rate_min, hi = p.interest_rate_max;
  if (lo == null) return "Rate: see lender website";
  return lo === hi || hi == null ? `Interest from ${Number(lo)}% p.a.` : `Interest ${Number(lo)}–${Number(hi)}% p.a.`;
}

/** The user's own data, held against each published rule — the "why" behind the match. */
function reasons(user, p) {
  const r = [];
  if (p.min_monthly_income != null) r.push(`income ${formatINR(user.monthly_income)}/month ≥ ${formatINR(p.min_monthly_income)} minimum`);
  if (p.min_credit_score != null && user.credit_score != null) r.push(`credit score ${user.credit_score} ≥ ${p.min_credit_score}`);
  if (p.min_age != null && p.max_age != null) r.push(`age ${user.age} within ${p.min_age}–${p.max_age}`);
  else if (p.min_age != null) r.push(`age ${user.age} ≥ ${p.min_age} minimum`);
  else if (p.max_age != null) r.push(`age ${user.age} ≤ ${p.max_age} maximum`);
  if (Array.isArray(p.employment_types) && p.employment_types.length) r.push(`${user.employment_status} applicants accepted`);
  return r;
}

const firstName = (name) => String(name ?? "").trim().split(/\s+/)[0] || "there";

/**
 * @param n  {user_id, name, monthly_income, credit_score, employment_status, age, products:[...]}
 * @param o  {unsubscribeBase, secret, now (seconds), maxCards,
 *            confirm?: {url, questions:[id], unlockable, lenders:[name]}  (questions.planQuestions + signed link)}
 */
/**
 * Pick cards across lenders: each lender's best product first (in score order), then second-best, ...
 * Without this, one lender's Salaried/Self-Employed variants can fill every card.
 */
function pickCards(products, max) {
  const byLender = new Map();
  for (const p of products) (byLender.get(p.lender_name) ?? byLender.set(p.lender_name, []).get(p.lender_name)).push(p);
  const out = [];
  for (let round = 0; out.length < max && out.length < products.length; round++) {
    for (const list of byLender.values()) if (list[round] && out.length < max) out.push(list[round]);
  }
  return out;
}

/** "A", "A and B", "A, B, C and 2 others" */
function listLenders(names, max = 3) {
  const shown = names.slice(0, max), rest = names.length - shown.length;
  if (rest > 0) return `${shown.join(", ")} and ${rest} other${rest === 1 ? "" : "s"}`;
  return shown.length > 1 ? `${shown.slice(0, -1).join(", ")} and ${shown[shown.length - 1]}` : (shown[0] ?? "");
}

/** The "answer a few questions" call to action, or null. Answers are self-declared: say so. */
function confirmPrompt(c) {
  if (!c || !c.url || !Array.isArray(c.questions) || !c.questions.length || !(c.unlockable > 0)) return null;
  const q = c.questions.length, m = c.unlockable;
  return {
    headline: `Answer ${q} quick question${q === 1 ? "" : "s"} to confirm up to ${m} offer${m === 1 ? "" : "s"}${c.lenders?.length ? ` from ${listLenders(c.lenders)}` : ""}`,
    note: "Some lenders ask for details we don't have yet. Tell us and we'll re-check — it takes under a minute. Your answers are self-declared: the lender verifies them when you apply.",
    url: c.url,
  };
}

function renderEmail(n, o) {
  const products = pickCards(n.products || [], o.maxCards ?? 5);
  const more = (n.products || []).length - products.length;
  const lenders = new Set((n.products || []).map((p) => p.lender_name)).size;
  const name = firstName(n.name);
  const token = unsubscribeToken(n.user_id, o.secret, o.now);
  const unsubscribeUrl = `${o.unsubscribeBase}?t=${encodeURIComponent(token)}`;
  const count = (n.products || []).length;
  const subject = `${name}, ${count} personal loan${count === 1 ? "" : "s"} you may qualify for`;
  const ask = confirmPrompt(o.confirm);

  const cards = products.map((p) => {
    const why = reasons(n, p).map((r) => `<li>${escapeHtml(r)}</li>`).join("");
    const todo = (p.unverified || []).map((u) => `<li>${escapeHtml(u)}</li>`).join("");
    return `<tr><td style="padding:16px;border:1px solid #e4e4e7;border-radius:12px;background:#ffffff">
<div style="font-size:12px;color:#71717a;text-transform:uppercase;letter-spacing:.04em">${escapeHtml(p.lender_name)}</div>
<div style="font-size:18px;font-weight:700;color:#18181b;margin:2px 0 6px">${escapeHtml(p.product_name)}</div>
<div style="font-size:15px;color:#18181b">${escapeHtml(rateText(p))}${p.max_loan_amount ? ` · up to ${formatINR(p.max_loan_amount)}` : ""}</div>
${why ? `<div style="margin-top:10px;font-size:14px;color:#15803d;font-weight:600">Why you may qualify</div><ul style="margin:4px 0 0;padding-left:18px;font-size:14px;color:#3f3f46">${why}</ul>` : ""}
${todo ? `<div style="margin-top:10px;font-size:14px;color:#a16207;font-weight:600">Still to confirm with the lender</div><ul style="margin:4px 0 0;padding-left:18px;font-size:14px;color:#3f3f46">${todo}</ul>` : ""}
<div style="margin-top:14px"><a href="${escapeHtml(p.source_url)}" style="display:inline-block;background:#4338ca;color:#ffffff;text-decoration:none;padding:10px 16px;border-radius:8px;font-size:14px;font-weight:600">View on ${escapeHtml(p.lender_name)}</a></div>
</td></tr><tr><td style="height:12px"></td></tr>`;
  }).join("");

  const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>${escapeHtml(subject)}</title></head>
<body style="margin:0;background:#f4f4f5;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif">
<div style="display:none;max-height:0;overflow:hidden">Based on your profile — checking these doesn't affect your credit score.</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px">
<tr><td style="padding:0 4px 16px;font-size:16px;color:#18181b">Hi ${escapeHtml(name)},<br><br>Based on the details shared with us, you may be eligible for these personal loans:</td></tr>
${ask ? `<tr><td style="padding:16px;border:1px solid #fde68a;border-radius:12px;background:#fffbeb">
<div style="font-size:16px;font-weight:700;color:#18181b">${escapeHtml(ask.headline)}</div>
<div style="margin-top:6px;font-size:14px;line-height:1.5;color:#3f3f46">${escapeHtml(ask.note)}</div>
<div style="margin-top:12px"><a href="${escapeHtml(ask.url)}" style="display:inline-block;background:#a16207;color:#ffffff;text-decoration:none;padding:10px 16px;border-radius:8px;font-size:14px;font-weight:600">Answer the questions</a></div>
</td></tr><tr><td style="height:12px"></td></tr>` : ""}
${cards}
${more > 0 ? `<tr><td style="padding:0 4px 12px;font-size:14px;color:#3f3f46">+ ${more} more option${more === 1 ? "" : "s"} matched your profile, across ${lenders} lender${lenders === 1 ? "" : "s"} in total.</td></tr>` : ""}
<tr><td style="padding:8px 4px;font-size:12px;line-height:1.5;color:#71717a">These are indicative matches based on publicly listed criteria — not loan offers or approvals. Final eligibility, rates and amounts are decided by the lender.<br><br>
You're receiving this because you shared your details for loan offers. <a href="${escapeHtml(unsubscribeUrl)}" style="color:#71717a">Unsubscribe</a></td></tr>
</table></td></tr></table></body></html>`;

  const text = [
    `Hi ${name},`, "", "Based on the details shared with us, you may be eligible for these personal loans:", "",
    ...(ask ? [`${ask.headline}:`, ask.url, ask.note, ""] : []),
    ...products.flatMap((p) => [
      `• ${p.product_name} — ${p.lender_name}`, `  ${rateText(p)}`,
      ...reasons(n, p).map((r) => `  ✓ ${r}`), ...(p.unverified || []).map((u) => `  ? To confirm: ${u}`),
      `  ${p.source_url}`, "",
    ]),
    more > 0 ? `+ ${more} more option(s) matched your profile, across ${lenders} lender(s) in total.\n` : "",
    "Indicative matches only — not loan offers. The lender decides final eligibility.",
    `Unsubscribe: ${unsubscribeUrl}`,
  ].join("\n");

  return { subject, html, text };
}

if (typeof module !== "undefined") {
  module.exports = { renderEmail, pickCards, unsubscribeToken, formatINR, escapeHtml, reasons, listLenders, confirmPrompt };
}

return module.exports; })();
// ---- questions.js (source: apps/workflows/src/code/questions.js — edit there, then rebuild) ----
const questions = (() => { const module = { exports: {} };
// Workflow C/D helpers: which "to confirm" questions to ask a person, and the signed link to ask them.
//
// A LIKELY match is blocked by soft rules about data the CSV doesn't have (work experience,
// employer type, bank relationship...). Across 10,000 real users only ~5 unknown facts block
// tens of thousands of matches, so a few well-chosen questions unlock most of them. The planner
// picks, per person, the ≤ 3 questions that unlock the most offers worth showing.
// Answers are SELF-DECLARED: the lender still verifies documents at application.

const crypto = require("crypto");

const EMPLOYER_TYPES = [
  ["central_state_govt", "Central / State Government"], ["psu", "Public sector undertaking (PSU)"],
  ["mnc", "Multinational company (MNC)"], ["public_ltd", "Public limited company"],
  ["private_ltd", "Private limited company"], ["partnership_proprietorship", "Partnership / Proprietorship"],
  ["other", "Other"],
];

/** Canonical question ids (shared with Workflow D's form and the console). Order = display order. */
const QUESTIONS = [
  { id: "work_experience", label: "How long have you been working?", answers: ["work_experience"],
    input: { type: "numbers", fields: [
      { name: "total_experience_years", label: "Total work experience (years)", min: 0, max: 60 },
      { name: "current_job_years", label: "Years with your current employer", min: 0, max: 60 }] } },
  { id: "employer_type", label: "Who do you work for?", answers: ["employer_type"],
    input: { type: "select", name: "employer_type", options: EMPLOYER_TYPES.map(([value, label]) => ({ value, label })) } },
  { id: "bank_accounts", label: "Do you have a savings or salary account with any of these banks?", answers: ["bank_relationship"],
    input: { type: "multiselect", name: "bank_accounts", options: "relevant_lenders", none: "none" } },
  { id: "city", label: "Which city do you live in?", answers: ["city"],
    input: { type: "text", name: "city", maxLength: 80 } },
  { id: "business_vintage", label: "How many years has your business been running?", answers: ["business_vintage"],
    input: { type: "number", name: "business_years", min: 0, max: 100 } },
  { id: "existing_emi", label: "How much do you pay in EMIs each month today?", answers: ["emi"],
    input: { type: "number", name: "existing_emi_monthly", min: 0, unit: "₹" } },
];
const QUESTION_BY_ID = Object.fromEntries(QUESTIONS.map((q) => [q.id, q]));
const ORDER = Object.fromEntries(QUESTIONS.map((q, i) => [q.id, i]));

const KNOWN_FEATURES = new Set(["monthly_income", "credit_score", "age", "employment_status"]);  // = matcher.js
const FEATURE_QUESTION = { work_experience: "work_experience", employer_type: "employer_type",
  bank_relationship: "bank_accounts", city: "city", business_vintage: "business_vintage" };
const EMI_RULE = /\bEMI|repay|obligation/i;

/**
 * Question ids that would let us re-check one soft rule, or null if no question can (stays LIKELY).
 * @param rule           {text, depends_on:[feature]}
 * @param verdictUnknown true when the rule only uses data we hold but the judge said UNKNOWN —
 *                       e.g. "income should be sufficient to repay the EMI": askable via existing EMIs.
 */
function askableQuestions(rule, verdictUnknown = false) {
  const deps = Array.isArray(rule?.depends_on) ? rule.depends_on : [];
  const emi = EMI_RULE.test(String(rule?.text ?? ""));
  const ids = new Set();
  for (const d of deps) {
    if (KNOWN_FEATURES.has(d)) continue;  // we already hold it
    if (FEATURE_QUESTION[d]) ids.add(FEATURE_QUESTION[d]);
    else if (d === "other" && emi) ids.add("existing_emi");
    else return null;  // "other" (non-EMI) or a feature we have no question for
  }
  if (!ids.size) {
    if (deps.length && verdictUnknown && emi) ids.add("existing_emi");
    else return null;  // nothing a person could tell us would change the verdict
  }
  return [...ids].sort((a, b) => ORDER[a] - ORDER[b]);
}

const num = (v) => (v === null || v === undefined || v === "" ? null : Number(v));
const productOf = (productsById, id) => (productsById instanceof Map ? productsById.get(Number(id)) ?? productsById.get(String(id))
  : productsById?.[id]) ?? null;
/** matcher.score() with nothing left unverified — what the offer would rank at once unlocked. */
const unlockedScore = (p) => Math.round((100 - (num(p?.interest_rate_min) ?? 30) * 2) * 100) / 100;

/**
 * Blocking question set for one LIKELY match, or null if any unverified rule can't be asked about.
 * Rule texts are looked up in the product's soft_rules; an unknown text (catalogue changed) → null.
 */
function blockingSet(match, product) {
  const rules = Array.isArray(product?.soft_rules) ? product.soft_rules : [];
  const unverified = Array.isArray(match.unverified) ? match.unverified : [];
  if (!unverified.length) return null;
  const ids = new Set();
  for (const text of unverified) {
    const rule = rules.find((r) => r.text === text);
    if (!rule) return null;
    // An unverified rule built only from known features means the judge couldn't decide (or never ran).
    const deps = Array.isArray(rule.depends_on) ? rule.depends_on : [];
    const asks = askableQuestions(rule, deps.length > 0 && deps.every((d) => KNOWN_FEATURES.has(d)));
    if (!asks) return null;
    asks.forEach((q) => ids.add(q));
  }
  return ids;
}

function* subsets(ids, max) {
  const n = ids.length;
  for (let mask = 1; mask < 1 << n; mask++) {
    const s = ids.filter((_, i) => mask & (1 << i));
    if (s.length <= max) yield s;
  }
}

const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s);

/**
 * Choose the questions to ask one person.
 * @param user          {user_id, ...} (unused today; kept so callers don't change if rules need it)
 * @param matches       [{product_id, status, score, unverified:[rule text]}]
 * @param productsById  {id: {id, lender_name, interest_rate_min, soft_rules}} or a Map
 * @returns {questions:[id], unlockable, lenders:[name], mentions:[{question, text}],
 *           bank_options:[lender name], product_ids:[id]}
 */
function planQuestions(user, matches, productsById, opts = {}) {
  const maxQuestions = opts.maxQuestions ?? 3, maxCards = opts.maxCards ?? 5;
  // Never ask twice: an offer still blocked by a question the person already answered can't be
  // helped by asking again (their answer was judged unclear, or it is waiting for the next re-check).
  const answered = new Set(opts.answered || []);
  const eligibleScores = (matches || []).filter((m) => m.status === "ELIGIBLE").map((m) => num(m.score) ?? 0);

  const candidates = [];
  for (const m of matches || []) {
    if (m.status !== "LIKELY") continue;
    const p = productOf(productsById, m.product_id);
    if (!p) continue;
    const blocking = blockingSet(m, p);
    if (!blocking || [...blocking].some((q) => answered.has(q))) continue;
    // Worth asking only if the unlocked offer would make the top cards; otherwise we'd ask for nothing.
    const s = unlockedScore(p);
    if (eligibleScores.filter((e) => e >= s).length >= maxCards) continue;
    candidates.push({ m, p, blocking, score: s });
  }
  const empty = { questions: [], unlockable: 0, lenders: [], mentions: [], bank_options: [], product_ids: [] };
  if (!candidates.length) return empty;

  // ≤ 6 ids → ≤ 63 subsets: exhaustive search is exact and cheap.
  const ids = [...new Set(candidates.flatMap((c) => [...c.blocking]))].sort((a, b) => ORDER[a] - ORDER[b]);
  let best = null;
  for (const s of subsets(ids, maxQuestions)) {
    const set = new Set(s);
    const unlocked = candidates.filter((c) => [...c.blocking].every((q) => set.has(q)));
    const value = unlocked.reduce((t, c) => t + c.score, 0);
    if (!best || unlocked.length > best.unlocked.length
        || (unlocked.length === best.unlocked.length && (s.length < best.s.length
            || (s.length === best.s.length && value > best.value)))) best = { s, unlocked, value };
  }
  if (!best.unlocked.length) return empty;

  const unlocked = [...best.unlocked].sort((a, b) => b.score - a.score);
  const lenders = [...new Set(unlocked.map((c) => c.p.lender_name))];
  const mentions = best.s.map((q) => {
    const c = unlocked.find((x) => x.blocking.has(q));
    const rule = c.m.unverified.find((t) => (askableQuestions(c.p.soft_rules.find((r) => r.text === t), true) || []).includes(q));
    return { question: q, text: clip(`${c.p.lender_name}: ${rule}`, 140) };
  });
  return {
    questions: best.s, unlockable: unlocked.length, lenders, mentions,
    bank_options: best.s.includes("bank_accounts") ? bankOptions(unlocked) : [],
    product_ids: unlocked.map((c) => Number(c.m.product_id)),
  };
}

/** Only lenders whose own rule asks about a banking relationship — not every bank we know of. */
function bankOptions(unlocked) {
  return [...new Set(unlocked.filter((c) => c.blocking.has("bank_accounts")).map((c) => c.p.lender_name))];
}

/**
 * Console aggregate over Workflow B's class × product rows. Every user in a class has the same
 * matches, so plan once per class and multiply by its size: O(classes), not O(users).
 * @param classRows  matcher.matchClasses().rows — {ib, cb, ab, emp, product_id, status, score, unverified}
 * @param opts       {maxQuestions, maxCards, classes:[{ib, cb, ab, emp, n}]} (row.n also accepted)
 * @returns {users_to_ask, unlockable_matches, by_question:[{id, label, users, unlockable}]}
 */
function planForClasses(classRows, productsById, opts = {}) {
  const key = (r) => `${r.ib}|${r.cb}|${r.ab}|${r.emp}`;
  const sizes = new Map((opts.classes || []).map((c) => [key(c), Number(c.n)]));
  const groups = new Map();
  for (const r of classRows || []) (groups.get(key(r)) ?? groups.set(key(r), []).get(key(r))).push(r);

  const out = { users_to_ask: 0, unlockable_matches: 0, by_question: [] };
  const byQ = new Map();
  for (const [k, rows] of groups) {
    const n = sizes.get(k) ?? Number(rows[0].n ?? 1);
    const plan = planQuestions(null, rows, productsById, opts);
    if (!plan.questions.length) continue;
    out.users_to_ask += n;
    out.unlockable_matches += n * plan.unlockable;
    for (const q of plan.questions) {
      const agg = byQ.get(q) ?? byQ.set(q, { id: q, label: QUESTION_BY_ID[q].label, users: 0, unlockable: 0 }).get(q);
      agg.users += n;
      // Matches that needed this question (a match needing two questions counts under both).
      agg.unlockable += n * plan.product_ids.filter((pid) => {
        const row = rows.find((r) => Number(r.product_id) === pid);
        return blockingSet(row, productOf(productsById, pid))?.has(q);
      }).length;
    }
  }
  out.by_question = [...byQ.values()].sort((a, b) => b.users - a.users || ORDER[a.id] - ORDER[b.id]);
  return out;
}

// ---- signed link -------------------------------------------------------------------------------
// Same secret as the unsubscribe token, domain-separated by the "c." prefix inside the MAC'd
// payload: an unsubscribe token can't open the form, and a confirm token can't unsubscribe.
const b64url = (buf) => Buffer.from(buf).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const mac = (payload, secret) => crypto.createHmac("sha256", String(secret)).update(payload).digest().subarray(0, 16);

function confirmToken(userId, secret, nowSeconds, ttl = 14 * 24 * 3600) {
  const payload = `c.${b64url(Buffer.from(String(userId), "utf8"))}.${nowSeconds + ttl}`;
  return `${payload}.${b64url(mac(payload, secret))}`;
}

/** `${WEBHOOK_URL}webhook/confirm?t=…`, tolerant of a missing trailing slash; null when unconfigured. */
function confirmLink(webhookBase, userId, secret, nowSeconds) {
  const base = String(webhookBase ?? "").trim();
  if (!base || !secret) return null;
  return `${base.replace(/\/*$/, "/")}webhook/confirm?t=${encodeURIComponent(confirmToken(userId, secret, nowSeconds))}`;
}

/** → {ok: true, userId} | {ok: false, reason}. The reason is for logs, never for the page. */
function verifyConfirmToken(token, secret, nowSeconds) {
  if (!secret) return { ok: false, reason: "no secret" };
  const parts = String(token ?? "").split(".");
  if (parts.length !== 4 || parts[0] !== "c" || !/^\d+$/.test(parts[2])) return { ok: false, reason: "malformed" };
  const expected = mac(parts.slice(0, 3).join("."), secret);
  const given = Buffer.from(parts[3].replace(/-/g, "+").replace(/_/g, "/"), "base64");
  if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) return { ok: false, reason: "bad signature" };
  if (Number(parts[2]) <= nowSeconds) return { ok: false, reason: "expired" };
  const userId = Buffer.from(parts[1].replace(/-/g, "+").replace(/_/g, "/"), "base64").toString("utf8");
  return userId ? { ok: true, userId } : { ok: false, reason: "malformed" };
}

if (typeof module !== "undefined") {
  module.exports = { QUESTIONS, EMPLOYER_TYPES, askableQuestions, planQuestions, planForClasses,
                     unlockedScore, confirmToken, verifyConfirmToken, confirmLink };
}

return module.exports; })();
// ---- confirm.js (source: apps/workflows/src/code/confirm.js — edit there, then rebuild) ----
const confirm = (() => { const module = { exports: {} };
// Workflow D helpers: the "confirm a few details" form, answer checks, re-judging a person's
// LIKELY matches with their answers, and the "you now pre-qualify" page + email.
//
// Answers are SELF-DECLARED. Nothing here says "approved": an unlocked match is "pre-qualified
// based on your answers", and the lender verifies documents at application. Answers that
// contradict each other (or the CSV) are flagged for ops and never used.
//
// Depends on questions.js (question metadata, askableQuestions) and email.js (escaping, INR,
// card helpers). In n8n those modules are inlined before this one (build.py include()), so the
// names `questions` / `email` already exist; under node --test they are required.

/* eslint-disable no-undef */
const Q = typeof questions !== "undefined" ? questions : require("./questions.js");
const E = typeof email !== "undefined" ? email : require("./email.js");
/* eslint-enable no-undef */

const { escapeHtml, formatINR } = E;
const KNOWN_FEATURES = new Set(["monthly_income", "credit_score", "age", "employment_status"]);  // = matcher.js
const QUESTION_BY_ID = Object.fromEntries(Q.QUESTIONS.map((q) => [q.id, q]));
const EMPLOYER_LABEL = Object.fromEntries(Q.EMPLOYER_TYPES);
// Employer types only an employee can have. (Not the reverse: a salaried person can work for a
// partnership or proprietorship firm, so that answer is never a contradiction.)
const SALARIED_EMPLOYERS = new Set(["central_state_govt", "psu", "mnc", "public_ltd", "private_ltd"]);
const MAX_EMI = 10_000_000;  // ₹1 crore a month: anything above is a typo, not an answer
const MIN_WORKING_AGE = 18;

const num = (v) => (v === null || v === undefined || v === "" ? null : Number(v));
const firstName = (name) => String(name ?? "").trim().split(/\s+/)[0] || "there";
const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;
const years = (n) => `${n} year${Number(n) === 1 ? "" : "s"}`;
const asList = (v) => (v === undefined || v === null ? [] : Array.isArray(v) ? v : [v]).map((x) => String(x));

function rateText(p) {
  const lo = num(p.interest_rate_min), hi = num(p.interest_rate_max);
  if (lo === null) return "Rate: see lender website";
  return hi === null || lo === hi ? `Interest from ${lo}% p.a.` : `Interest ${lo}–${hi}% p.a.`;
}

/** matcher.score(): cheaper credit first, −5 per condition still to confirm. */
function score(product, unverifiedCount) {
  const rate = num(product.interest_rate_min);
  return Math.round((100 - (rate === null ? 30 : rate) * 2 - unverifiedCount * 5) * 100) / 100;
}

// ---- person / plan -----------------------------------------------------------------------------

/**
 * Split the loaded row (d_load_person.sql) into what questions.planQuestions() expects.
 * @returns {user, matches, productsById, likely}
 */
function planInputs(person) {
  const all = Array.isArray(person?.matches) ? person.matches : [];
  const productsById = {};
  for (const m of all) productsById[m.product_id] = { id: m.product_id, lender_name: m.lender_name,
    interest_rate_min: m.interest_rate_min, soft_rules: m.soft_rules || [] };
  const matches = all.map((m) => ({ product_id: m.product_id, status: m.status, score: num(m.score),
    unverified: Array.isArray(m.unverified) ? m.unverified : [] }));
  const user = { user_id: person?.user_id, age: person?.age, employment_status: person?.employment_status };
  return { user, matches, productsById, likely: all.filter((m) => m.status === "LIKELY") };
}

/** Banks a person may tick: the planner's list, else every lender they matched (lenient on re-submits). */
function allowedBanks(person, plan) {
  const fromPlan = Array.isArray(plan?.bank_options) ? plan.bank_options : [];
  const fromMatches = (person?.matches || []).map((m) => m.lender_name).filter(Boolean);
  return [...new Set([...fromPlan, ...fromMatches])];
}

// ---- answers -----------------------------------------------------------------------------------

/** Form field values (strings) from stored answers, for pre-filling the form. */
function answersToValues(answers) {
  const a = answers || {}, v = {};
  if (a.work_experience) {
    v.total_experience_years = String(a.work_experience.total_experience_years ?? "");
    v.current_job_years = String(a.work_experience.current_job_years ?? "");
  }
  if (a.employer_type) v.employer_type = String(a.employer_type);
  if (Array.isArray(a.bank_accounts)) v.bank_accounts = a.bank_accounts.length ? a.bank_accounts.map(String) : ["none"];
  if (a.city) v.city = String(a.city);
  if (a.business_vintage) v.business_years = String(a.business_vintage.business_years ?? "");
  if (a.existing_emi) v.existing_emi_monthly = String(a.existing_emi.existing_emi_monthly ?? "");
  return v;
}

/** Form body → raw field values. Accepts `name` repeated or `name[]` (body parsers differ). */
function formValues(body) {
  const b = body && typeof body === "object" ? body : {};
  const pick = (k) => (b[k] !== undefined ? b[k] : b[`${k}[]`]);
  const one = (k) => { const x = asList(pick(k)); return x.length ? x[0].trim().slice(0, 200) : ""; };
  return {
    total_experience_years: one("total_experience_years"), current_job_years: one("current_job_years"),
    employer_type: one("employer_type"),
    bank_accounts: asList(pick("bank_accounts")).map((s) => s.trim().slice(0, 200)).filter(Boolean),
    city: one("city"), business_years: one("business_years"), existing_emi_monthly: one("existing_emi_monthly"),
  };
}

function parseNumber(raw, { min, max, integer = false }) {
  const s = String(raw).replace(/[₹,\s]/g, "");
  if (!/^\d+(\.\d+)?$/.test(s)) return { error: "Please enter a number, like 3 or 2.5." };
  const n = Number(s);
  if (integer && !Number.isInteger(n)) return { error: "Please enter a whole number of rupees." };
  if (n < min || n > max) return { error: `Please enter a number between ${min} and ${max.toLocaleString("en-IN")}.` };
  return { value: n };
}

/**
 * Parse + validate submitted answers. Invalid input (not a number, out of range, unknown option)
 * is returned as `errors` per question so the form can be shown again — nothing is stored.
 * Blank questions are skipped; at least one answer is required.
 * @returns {answers: {question_id: value}, errors: {question_id|"form": message}}
 */
function parseAnswers(body, person, plan) {
  const v = formValues(body);
  const answers = {}, errors = {};
  const range = (qid, field) => {
    const input = QUESTION_BY_ID[qid].input;
    const f = input.fields ? input.fields.find((x) => x.name === field) : input;
    return { min: f.min ?? 0, max: f.max ?? MAX_EMI };
  };

  if (v.total_experience_years || v.current_job_years) {
    if (!v.total_experience_years || !v.current_job_years) errors.work_experience = "Please fill in both numbers.";
    else {
      const t = parseNumber(v.total_experience_years, range("work_experience", "total_experience_years"));
      const c = parseNumber(v.current_job_years, range("work_experience", "current_job_years"));
      if (t.error || c.error) errors.work_experience = t.error || c.error;
      else answers.work_experience = { total_experience_years: t.value, current_job_years: c.value };
    }
  }
  if (v.employer_type) {
    if (EMPLOYER_LABEL[v.employer_type]) answers.employer_type = v.employer_type;
    else errors.employer_type = "Please choose one of the options.";
  }
  if (v.bank_accounts.length) {
    const allowed = new Set(allowedBanks(person, plan));
    const banks = [...new Set(v.bank_accounts)];
    if (banks.includes("none") && banks.length > 1) errors.bank_accounts = "Choose banks, or “None of these” — not both.";
    else if (banks.some((b) => b !== "none" && !allowed.has(b))) errors.bank_accounts = "Please choose from the banks listed.";
    else answers.bank_accounts = banks.filter((b) => b !== "none");
  }
  if (v.city) {
    const city = v.city.replace(/\s+/g, " ").trim();
    if (city.length < 2 || city.length > 80 || !/^[\p{L}][\p{L}\p{M} .'-]*$/u.test(city)) errors.city = "Please enter your city's name.";
    else answers.city = city;
  }
  if (v.business_years) {
    const b = parseNumber(v.business_years, range("business_vintage", "business_years"));
    if (b.error) errors.business_vintage = b.error;
    else answers.business_vintage = { business_years: b.value };
  }
  if (v.existing_emi_monthly) {
    const e = parseNumber(v.existing_emi_monthly, { ...range("existing_emi", "existing_emi_monthly"), integer: true });
    if (e.error) errors.existing_emi = e.error;
    else answers.existing_emi = { existing_emi_monthly: e.value };
  }
  if (!Object.keys(answers).length && !Object.keys(errors).length) errors.form = "Please answer at least one question.";
  return { answers, errors, values: v };
}

/**
 * The plan to re-show the form with after invalid input: the planned questions plus any the
 * person filled in (the plan may have changed since the form was served), in canonical order.
 */
function retryPlan(plan, parsed) {
  const v = parsed.values || {};
  const touched = new Set(Object.keys(parsed.errors || {}).filter((k) => QUESTION_BY_ID[k]));
  Object.keys(parsed.answers || {}).forEach((k) => touched.add(k));
  if (v.total_experience_years || v.current_job_years) touched.add("work_experience");
  if (v.employer_type) touched.add("employer_type");
  if ((v.bank_accounts || []).length) touched.add("bank_accounts");
  if (v.city) touched.add("city");
  if (v.business_years) touched.add("business_vintage");
  if (v.existing_emi_monthly) touched.add("existing_emi");
  (plan?.questions || []).forEach((q) => touched.add(q));
  const questions = Q.QUESTIONS.map((q) => q.id).filter((id) => touched.has(id));
  return { ...(plan || {}), questions, unlockable: plan?.unlockable ?? 0, mentions: plan?.mentions || [], lenders: plan?.lenders || [] };
}

/** Newer answers replace older ones per question; questions not asked this time are kept. */
const mergeAnswers = (previous, fresh) => ({ ...(previous && typeof previous === "object" ? previous : {}), ...fresh });

/**
 * Contradictions between answers, or with the CSV. Any reason → the declaration is flagged for
 * ops review and not used. Reasons are for ops, never shown to the person.
 */
function sanityCheck(answers, person) {
  const reasons = [];
  const age = num(person?.age), emp = person?.employment_status;
  const maxYears = age === null ? null : age - MIN_WORKING_AGE;
  const we = answers.work_experience;
  if (we) {
    if (maxYears !== null && we.total_experience_years > maxYears)
      reasons.push(`total experience ${years(we.total_experience_years)} > age ${age} − ${MIN_WORKING_AGE}`);
    if (we.current_job_years > we.total_experience_years)
      reasons.push(`current job ${years(we.current_job_years)} > total experience ${years(we.total_experience_years)}`);
  }
  const bv = answers.business_vintage;
  if (bv && maxYears !== null && bv.business_years > maxYears)
    reasons.push(`business running ${years(bv.business_years)} > age ${age} − ${MIN_WORKING_AGE}`);
  const et = answers.employer_type;
  if (et && emp && emp !== "Salaried" && SALARIED_EMPLOYERS.has(et))
    reasons.push(`${emp} applicant chose a salaried employer type (${et})`);
  const emi = answers.existing_emi?.existing_emi_monthly, income = num(person?.monthly_income);
  if (emi != null && income !== null && emi > income)
    reasons.push(`existing EMIs ${formatINR(emi)}/month > monthly income ${formatINR(income)}`);
  return reasons;
}

// ---- re-judging --------------------------------------------------------------------------------

const answered = (answers, qid) => answers[qid] !== undefined;

/** What the judge sees for one rule: the person's exact CSV values + their declared answers. */
function judgeFeatures(person, answers, rule, asks) {
  const f = {};
  const deps = Array.isArray(rule.depends_on) ? rule.depends_on : [];
  const known = {
    monthly_income: num(person.monthly_income),
    credit_score: person.credit_score == null ? "no credit history" : num(person.credit_score),
    age: num(person.age), employment_status: person.employment_status,
  };
  for (const d of deps) if (KNOWN_FEATURES.has(d)) f[d] = known[d];
  for (const q of asks) {
    const a = answers[q];
    if (q === "work_experience") f.work_experience = { total_years: a.total_experience_years, years_in_current_job: a.current_job_years };
    if (q === "employer_type") f.employer_type = EMPLOYER_LABEL[a] ?? a;
    if (q === "bank_accounts") f.bank_relationship = a.length
      ? `has a savings or salary account with: ${a.join(", ")}`
      : "has no savings or salary account with any of the banks asked about";
    if (q === "city") f.city = a;
    if (q === "business_vintage") f.business_vintage = { years: a.business_years };
    if (q === "existing_emi") {
      f.existing_emi_monthly_inr = a.existing_emi_monthly;
      f.monthly_income = known.monthly_income;
    }
  }
  f.source = "applicant's own declaration; the lender verifies documents at application";
  return f;
}

/**
 * One judge item per unverified rule of a LIKELY match that the answers now cover.
 * cache_key is per request (`product:index`): personal answers are never written to the shared
 * LLM cache, which is keyed by class ranges.
 * @returns [{cache_key, product_id, rule, features}]  — the shape llm.judgmentRequest() takes
 */
function judgeItems(person, answers) {
  const items = [];
  for (const m of planInputs(person).likely) {
    const rules = Array.isArray(m.soft_rules) ? m.soft_rules : [];
    (Array.isArray(m.unverified) ? m.unverified : []).forEach((text, i) => {
      const rule = rules.find((r) => r.text === text);
      if (!rule) return;  // catalogue changed since matching: leave it for the next match run
      const deps = Array.isArray(rule.depends_on) ? rule.depends_on : [];
      const asks = Q.askableQuestions(rule, deps.length > 0 && deps.every((d) => KNOWN_FEATURES.has(d)));
      if (!asks || !asks.every((q) => answered(answers, q))) return;
      items.push({ cache_key: `${m.product_id}:${i}`, product_id: Number(m.product_id), rule: text,
                   features: judgeFeatures(person, answers, rule, asks) });
    });
  }
  return items;
}

/**
 * Apply verdicts to the person's LIKELY matches.
 *   every unverified rule PASS → "unlock"  (ELIGIBLE, decided_by DECLARED, unverified [])
 *   any FAIL                   → "reject"  (the match is deleted)
 *   some PASS, rest open       → "narrow"  (still LIKELY, fewer conditions, score recomputed)
 *   nothing judged             → no change
 * @param judgments llm.parseJudgments() output [{cache_key, verdict}]
 * @returns {updates:[{product_id, action, score, unverified}], unlocked:[match], narrowed, rejected}
 */
/**
 * Workflow B, after every (re-)match: people in the batch who answered before get their LIKELY
 * matches re-checked with those stored answers, so a new lender asking for the same fact never
 * asks the person twice. One judge request covers many people, so keys carry the user id.
 */
function batchJudgeItems(people) {
  const items = [];
  for (const person of people || []) {
    const answers = person.declared && typeof person.declared === "object" ? person.declared : {};
    for (const it of judgeItems(person, answers)) {
      items.push({ ...it, user_id: person.user_id, cache_key: `${person.user_id}|${it.cache_key}` });
    }
  }
  return items;
}

/** decide() per person over a shared verdict list → [{user_id, product_id, action, score, unverified}]. */
function batchDecide(people, items, judgments) {
  const updates = [];
  let unlocked = 0, narrowed = 0, rejected = 0;
  for (const person of people || []) {
    const prefix = `${person.user_id}|`;
    const strip = (x) => ({ ...x, cache_key: String(x.cache_key).slice(prefix.length) });
    const own = (items || []).filter((i) => String(i.cache_key).startsWith(prefix)).map(strip);
    if (!own.length) continue;
    const verdicts = (judgments || []).filter((j) => String(j.cache_key).startsWith(prefix)).map(strip);
    const d = decide(person, own, verdicts);
    for (const u of d.updates) updates.push({ user_id: person.user_id, ...u });
    unlocked += d.unlocked.length; narrowed += d.narrowed; rejected += d.rejected;
  }
  return { updates, unlocked, narrowed, rejected };
}

function decide(person, items, judgments) {
  const verdict = new Map((judgments || []).map((j) => [j.cache_key, j.verdict]));
  const judgedKeys = new Set((items || []).map((i) => i.cache_key));
  const updates = [], unlocked = [];
  let narrowed = 0, rejected = 0;
  for (const m of planInputs(person).likely) {
    const texts = Array.isArray(m.unverified) ? m.unverified : [];
    const keys = texts.map((_, i) => `${m.product_id}:${i}`);
    if (!keys.some((k) => judgedKeys.has(k) && verdict.has(k))) continue;
    if (keys.some((k) => judgedKeys.has(k) && verdict.get(k) === "FAIL")) {
      updates.push({ product_id: Number(m.product_id), action: "reject", score: num(m.score), unverified: texts });
      rejected++;
      continue;
    }
    const remaining = texts.filter((_, i) => !(judgedKeys.has(keys[i]) && verdict.get(keys[i]) === "PASS"));
    if (remaining.length === texts.length) continue;  // only UNKNOWNs: nothing changes
    if (!remaining.length) {
      updates.push({ product_id: Number(m.product_id), action: "unlock", score: score(m, 0), unverified: [] });
      unlocked.push({ ...m, status: "ELIGIBLE", unverified: [], score: score(m, 0) });
    } else {
      updates.push({ product_id: Number(m.product_id), action: "narrow", score: score(m, remaining.length), unverified: remaining });
      narrowed++;
    }
  }
  unlocked.sort((a, b) => b.score - a.score);
  return { updates, unlocked, narrowed, rejected };
}

