  for (let mask = 1; mask < 1 << n; mask++) {
    const s = ids.filter((_, i) => mask & (1 << i));
    if (s.length <= max) yield s;
  }
}

const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s);

/**
