  const n = Number(s);
  if (integer && !Number.isInteger(n)) return { error: "Please enter a whole number of rupees." };
  if (n < min || n > max) return { error: `Please enter a number between ${min} and ${max.toLocaleString("en-IN")}.` };
  return { value: n };
