  const payload = `c.${b64url(Buffer.from(String(userId), "utf8"))}.${nowSeconds + ttl}`;
  return `${payload}.${b64url(mac(payload, secret))}`;
}

/** `${WEBHOOK_URL}webhook/confirm?t=…`, tolerant of a missing trailing slash; null when unconfigured. */
